#define dprint_termc_add(p, end, s) \ /* <=== src/core/dprint.c:285:295:dprint_termc_add:3 */ 
        do{ \
                if ((p)+(sizeof(s)-1)<=(end)){ \
                        memcpy((p), s, sizeof(s)-1); \
