void tmx_pretran_link_safe(int slotid) /* <=== tmx_pretran_link_safe */ 
{
	if(_tmx_proc_ptran==NULL)
		return;

	if(_tmx_ptran_table[slotid].plist==NULL) {
		_tmx_ptran_table[slotid].plist = _tmx_proc_ptran;
		_tmx_proc_ptran->linked = 1;
		return;
	}
	_tmx_proc_ptran->next = _tmx_ptran_table[slotid].plist;
	_tmx_ptran_table[slotid].plist->prev = _tmx_proc_ptran;
	_tmx_ptran_table[slotid].plist = _tmx_proc_ptran;
	_tmx_proc_ptran->linked = 1;
	return;
}

void free_via_list(struct via_body *vb) /* <=== free_via_list */ 
{
	struct via_body *foo;
	while(vb) {
		foo = vb;
		vb = vb->next;
		if(foo->param_lst)
			free_via_param_list(foo->param_lst);
		pkg_free(foo);
	}
}

